document.addEventListener("DOMContentLoaded",()=>{setTimeout(()=>{const e=document.querySelector(".sub-nav-item.active"),t=document.querySelector(".subject-nav");if(e&&t){const n=t.offsetWidth,i=e.offsetLeft,r=e.offsetWidth;t.scrollLeft=i-n/2+r/2}},100);const s=document.querySelectorAll(".checklist-checkbox"),o="ssc-cgl-prep-checklist",c=JSON.parse(localStorage.getItem(o))||{};s.forEach(e=>{c[e.id]&&(e.checked=!0),e.addEventListener("change",()=>{c[e.id]=e.checked,localStorage.setItem(o,JSON.stringify(c))});const t=e.closest(".checklist-item");t&&t.addEventListener("click",n=>{n.target!==e&&(e.checked=!e.checked,e.dispatchEvent(new Event("change")))})})});
